// Extract vendor data from webhook payload
const vendor = $input.first().json;

const enriched = {
  vendor_id: vendor.vendor_id || `VND-${Date.now()}`,
  name: vendor.name || 'Unknown Vendor',
  address: vendor.address || '',
  phone: vendor.phone || '',
  lat: vendor.lat || 0,
  lng: vendor.lng || 0,
  city: vendor.city || '',
  state: vendor.state || 'Punjab',

  // Enrichment fields
  enriched: true,
  enriched_at: new Date().toISOString(),

  // Calculated fields
  verified: vendor.phone ? true : false,
  has_location: (vendor.lat && vendor.lng) ? true : false,

  // Product categorization
  products: vendor.products || [],
  product_categories: [],

  // Business intelligence
  rating: vendor.rating || null,
  operating_hours: vendor.operating_hours || '9:00 AM - 7:00 PM',
  accepts_digital_payment: vendor.accepts_digital_payment || false,
  delivery_available: vendor.delivery_available || false,
};

// Categorize products
const categories = new Set();
const productStr = (enriched.products || []).join(' ').toLowerCase();

if (productStr.match(/pesticide|कीटनाशक|insecticide|fungicide/)) categories.add('pesticides');
if (productStr.match(/fertilizer|खाद|urea|dap|npk/)) categories.add('fertilizers');
if (productStr.match(/seed|बीज|hybrid/)) categories.add('seeds');
if (productStr.match(/equipment|sprayer|pump|tool/)) categories.add('equipment');
if (productStr.match(/organic|जैविक|bio/)) categories.add('organic');

enriched.product_categories = Array.from(categories);

// Quality score (0-100)
let score = 0;
if (enriched.verified) score += 20;
if (enriched.has_location) score += 20;
if (enriched.rating) score += Math.min(enriched.rating * 5, 25);
if (enriched.products.length > 0) score += 15;
if (enriched.accepts_digital_payment) score += 10;
if (enriched.delivery_available) score += 10;

enriched.quality_score = Math.round(score);

return [{ json: enriched }];

// Log the enrichment execution
const vendor = $input.first().json;

const logEntry = {
  workflow: 'vendor_enrichment',
  timestamp: new Date().toISOString(),
  vendor_id: vendor.vendor_id || 'unknown',
  vendor_name: vendor.name || 'unknown',
  quality_score: vendor.quality_score || 0,
  categories: vendor.product_categories || [],
  enriched: true,
  status: 'completed'
};

console.log('[Krishi-Sarthi] Vendor enrichment:', JSON.stringify(logEntry));

return [{ json: logEntry }];
